'use strict';
let studySubject='all', studyQuery='', studyResults=[], studySearching=false, studySearchError='', studySearchPage=0, studySearchToken=0, readerTextMode=false, readerLoadToken=0;
const textbookIndexCache=new Map();
let readingPositions={};
try{readingPositions=JSON.parse(localStorage.getItem('medico-reading-positions')||'{}');if(!readingPositions||typeof readingPositions!=='object'||Array.isArray(readingPositions))readingPositions={};}catch{readingPositions={};}
function textbook(id){return TEXTBOOKS.find(b=>b.id===id);}
function safeBookPage(b,n){const v=Number(n);return Number.isInteger(v)&&v>=1?Math.min(v,b.pages):1;}
function rememberBookPage(b,p){readingPositions[b.id]=p;try{localStorage.setItem('medico-reading-positions',JSON.stringify(readingPositions));}catch{}}
function textbookCredit(b){return `<p class="textbook-credit">${esc(b.title)} · ${esc(b.author)} · ${b.year}. <a href="${esc(b.source)}" target="_blank" rel="noopener">Publisher & original edition ↗</a> · <a href="${esc(b.licenseUrl)}" target="_blank" rel="noopener">${esc(b.license)}</a>. Original PDF unmodified; source figure credits retained. Text extraction and search index share the book’s license.</p>`;}
function bookChapter(b,p){const candidates=b.chapters.filter(c=>c.page<=p).sort((a,b)=>a.page-b.page);return candidates.length?candidates[candidates.length-1]:b.chapters[0];}
function bookCard(b){const resume=safeBookPage(b,readingPositions[b.id]);return `<article class="textbook-card"><a class="textbook-cover cover-${b.id}" href="#book/${b.id}/${resume}"><span>${esc(b.publisher.split(' · ')[0])}</span><h3>${esc(b.shortTitle)}</h3><div>${b.pages} pages · ${b.chapters.length} indexed sections</div></a><div class="textbook-card-body"><span class="eyebrow">${esc(b.level)} · ${b.year}</span><p>${esc(b.description)}</p><div class="material-tags">${b.subjects.map(id=>`<span>${esc(subj(id).name)}</span>`).join('')}</div><a class="btn" href="#book/${b.id}/${resume}">${resume>1?'Continue on PDF page '+resume:'Start full textbook'} →</a><p class="fine">${esc(b.license)} · Full book stored locally</p></div></article>`;}
function studyLibrary(){main.innerHTML=`<div class="page-head"><span class="eyebrow">FROM THE CONCEPT TO THE COMPLETE CHAPTER</span><h1>Study in depth.</h1><p>Full university textbooks with mechanisms, pathways, figures, comparison tables and source learning activities. Browse their chapters, search every page, and continue where you left off.</p><div class="metric-line"><span>${TEXTBOOKS.length} full textbooks</span><span>${TEXTBOOKS.reduce((n,b)=>n+b.pages,0).toLocaleString()} PDF pages</span><span>${TEXTBOOKS.reduce((n,b)=>n+b.chapters.length,0)} indexed sections</span><span>Downloaded for local reading</span></div></div><section class="study-search-panel"><form id="study-search-form"><label for="study-search">Search the full textbook text</label><div class="study-search-row"><input id="study-search" type="search" minlength="2" maxlength="160" placeholder="Try nephron, Frank-Starling, beta blockers, glycolysis…" value="${esc(studyQuery)}"><button class="btn" type="submit">Search textbooks</button></div><p class="fine">Search runs when you submit. Text indexes load once per book; short passages link to the exact PDF page.</p></form><label for="study-subject">Filter by subject</label><select id="study-subject">${options(studySubject)}</select></section><div id="study-search-results" aria-live="polite"></div><div class="section-title"><h2>Choose a full textbook</h2><a class="btn secondary" href="#resources">Image reference library →</a></div><div id="study-book-grid" class="textbook-grid"></div><div class="notice study-scope">The university books focus on selected pre-clinical medical sciences. Open RN books are nursing references and label US practice and legal context. These editions supplement the medical curriculum; specialist subjects still need dedicated texts and current Indian examination references.</div>`;renderStudyBooks();renderStudyResults();}
function renderStudyBooks(){const bs=TEXTBOOKS.filter(b=>studySubject==='all'||b.subjects.includes(studySubject));$('#study-book-grid').innerHTML=bs.length?bs.map(bookCard).join(''):`<div class="empty"><h3>No full textbook has been imported for ${esc(subj(studySubject)?.name||'this subject')}.</h3><p>Use the subject’s existing lessons and original reference directory.</p><a class="btn secondary" href="#subject/${esc(studySubject)}">Open subject</a></div>`;}
async function loadBookIndex(b){if(textbookIndexCache.has(b.id))return textbookIndexCache.get(b.id);const request=fetch('textbooks/'+b.searchFile).then(r=>{if(!r.ok)throw new Error('Could not load '+b.shortTitle);return r.json();}).then(data=>{if(!Array.isArray(data.pages))throw new Error('Invalid textbook index');return data;}).catch(error=>{textbookIndexCache.delete(b.id);throw error;});textbookIndexCache.set(b.id,request);return request;}
function textbookSearchMatches(pages,query){const words=query.toLowerCase().trim().split(/\s+/).filter(Boolean).slice(0,10);if(!words.length)return [];return pages.filter(p=>words.every(w=>p.text.toLowerCase().includes(w)));}
function excerptHighlight(text,query){const needle=query.trim().toLowerCase().split(/\s+/)[0]||'';const at=text.toLowerCase().indexOf(needle);if(at<0)return esc(text.slice(0,260));const start=Math.max(0,at-85),end=Math.min(text.length,at+needle.length+155);return (start?'…':'')+esc(text.slice(start,at))+'<mark>'+esc(text.slice(at,at+needle.length))+'</mark>'+esc(text.slice(at+needle.length,end))+(end<text.length?'…':'');}
async function searchTextbooks(query){studyQuery=String(query).trim().slice(0,160);studySearchPage=0;studyResults=[];studySearchError='';const token=++studySearchToken;if(studyQuery.length<2){studySearching=false;studySearchError='Enter at least two characters to search.';renderStudyResults();return;}studySearching=true;renderStudyResults();const bs=TEXTBOOKS.filter(b=>studySubject==='all'||b.subjects.includes(studySubject));const settled=await Promise.allSettled(bs.map(async b=>({book:b,data:await loadBookIndex(b)})));if(token!==studySearchToken)return;studySearching=false;const failed=settled.filter(r=>r.status==='rejected');if(failed.length)studySearchError=`${failed.length} book index(es) could not load. You can still open the PDFs below.`;for(const result of settled){if(result.status!=='fulfilled')continue;const {book:b,data}=result.value;for(const page of textbookSearchMatches(data.pages,studyQuery))studyResults.push({book:b.id,page:page.page,text:page.text});}if((location.hash||'')==='#study')renderStudyResults();}
function renderStudyResults(){const el=$('#study-search-results');if(!el)return;if(studySearching){el.innerHTML='<section class="panel study-results"><p role="status">Searching the full textbook text…</p></section>';return;}if(!studyQuery&&!studySearchError){el.innerHTML='';return;}const total=studyResults.length,maxPage=Math.max(0,Math.ceil(total/12)-1);studySearchPage=Math.min(studySearchPage,maxPage);const visible=studyResults.slice(studySearchPage*12,studySearchPage*12+12);el.innerHTML=`<section class="study-results panel"><div class="section-title"><h2>${total} matching pages</h2><button class="btn secondary" data-action="study-clear">Clear search</button></div>${studySearchError?`<p class="error-note">${esc(studySearchError)}</p>`:''}${total?visible.map(r=>{const b=textbook(r.book);return `<article class="textbook-search-hit"><span class="eyebrow">${esc(b.shortTitle)} · PDF PAGE ${r.page}</span><h3><a href="#book/${b.id}/${r.page}">${esc(bookChapter(b,r.page)?.title||b.shortTitle)} →</a></h3><p>${excerptHighlight(r.text,studyQuery)}</p></article>`}).join(''):'<p>No matching pages in the selected books. Try a shorter term or another subject.</p>'}${total>12?`<div class="pager"><button class="btn secondary" data-action="study-prev" ${studySearchPage===0?'disabled':''}>Previous results</button><span>${studySearchPage*12+1}–${Math.min(total,(studySearchPage+1)*12)} of ${total}</span><button class="btn secondary" data-action="study-next" ${studySearchPage===maxPage?'disabled':''}>Next results</button></div>`:''}</section>`;}
function bookPage(id,rawPage){const b=textbook(id);if(!b)return notFound();const p=safeBookPage(b,rawPage||readingPositions[id]);rememberBookPage(b,p);const chapter=bookChapter(b,p);main.innerHTML=`<article class="book-reader"><div class="book-reader-head"><a class="eyebrow" href="#study">IN-DEPTH LIBRARY / ${esc(b.level.toUpperCase())}</a><h1>${esc(b.shortTitle)}</h1><p class="muted">${esc(b.author)} · ${b.year} · ${b.pages} PDF pages</p></div><div class="reader-layout"><aside class="reader-contents panel"><h2>Chapter browser</h2><label class="sr-only" for="reader-chapter-search">Filter chapter headings</label><input type="search" id="reader-chapter-search" placeholder="Find a chapter heading…"><nav id="reader-chapters" aria-label="Textbook contents">${bookChapterLinks(b,p)}</nav><a class="btn secondary" href="textbooks/${b.file}" download>Download original PDF</a><a class="reference-source" href="${esc(b.source)}" target="_blank" rel="noopener">Accessible publisher edition ↗</a></aside><section class="reader-main"><div class="reader-toolbar"><div><strong>PDF page ${p} / ${b.pages}</strong><p class="fine">${esc(chapter?.title||'Textbook')}</p></div><div class="reader-page-controls"><button class="btn secondary" data-action="reader-prev" data-id="${id}" data-page="${p}" ${p===1?'disabled':''}>← Previous</button><form id="reader-page-form" data-book="${id}"><label class="sr-only" for="reader-page-number">Go to PDF page</label><input id="reader-page-number" type="number" min="1" max="${b.pages}" value="${p}" required><button class="btn secondary" type="submit">Go</button></form><button class="btn secondary" data-action="reader-next" data-id="${id}" data-page="${p}" ${p===b.pages?'disabled':''}>Next →</button></div></div><p class="reader-beginner-link">Unfamiliar language? <a href="#words" target="_blank" rel="noopener">Open the medical word guide in a new tab</a>, or <a href="#subject/foundation">start with the foundation lessons</a>.</p><div class="reader-mode-bar"><button class="btn ${readerTextMode?'secondary':''}" data-action="reader-mode" data-id="pdf" aria-pressed="${!readerTextMode}">Original pages & figures</button><button class="btn ${readerTextMode?'':'secondary'}" data-action="reader-mode" data-id="text" aria-pressed="${readerTextMode}">Text view</button><a class="btn ghost" href="textbooks/${b.file}#page=${p}" target="_blank" rel="noopener">Open PDF in a new tab ↗</a></div><div id="reader-surface">${readerTextMode?'<div class="reader-text"><p>Loading page text…</p></div>':`<iframe class="textbook-pdf" src="textbooks/${b.file}#page=${p}&view=FitH" title="${esc(b.title)}, PDF page ${p}"></iframe><p class="fine">If the embedded PDF is unavailable in your browser, use Text view or open the PDF above. PDF page numbers include cover and front matter.</p>`} </div>${textbookCredit(b)}<p class="fine">Last position is saved on this device. To keep it synchronized with these controls, navigate using the buttons or chapter browser.</p></section></div></article>`;if(readerTextMode)renderBookText(b,p);}
function bookChapterLinks(b,p,filter=''){const q=filter.trim().toLowerCase();const current=bookChapter(b,p);const chapters=b.chapters.filter(c=>c.title.toLowerCase().includes(q));return chapters.length?chapters.map(c=>`<a href="#book/${b.id}/${c.page}" class="reader-chapter ${current===c?'current':''}" style="--chapter-level:${Math.min(c.level,3)}" ${current===c?'aria-current="page"':''}><span>${esc(c.title)}</span><small>p. ${c.page}</small></a>`).join(''):'<p class="fine">No chapter headings match.</p>';}
async function renderBookText(b,p){const token=++readerLoadToken;try{const data=await loadBookIndex(b);if(token!==readerLoadToken||!location.hash.startsWith(`#book/${b.id}`)||!readerTextMode)return;const page=data.pages.find(x=>x.page===p);$('#reader-surface').innerHTML=`<div class="reader-text"><p class="notice">Extracted text view. Use the original PDF for the layout of equations, comparison tables and diagrams.</p><div class="extracted-page">${esc(page?.text||'This page contains artwork or no extractable text.')}</div></div>`;}catch{if(token===readerLoadToken&&readerTextMode&&location.hash.startsWith('#book/'+b.id+'/'))$('#reader-surface').innerHTML='<div class="reader-text"><p class="error-note">Page text could not load. Open the original PDF using the link above.</p></div>';}}
function subjectStudyBooks(id){const bs=TEXTBOOKS.filter(b=>b.subjects.includes(id));const guide=SUBJECT_GUIDES[id];return `<section class="subject-depth"><div class="section-title"><div><span class="eyebrow">READ THE FULL MECHANISM</span><h2>In-depth study material</h2></div><a class="btn" href="#study">Open full textbook library →</a></div>${guide?`<section class="study-guide panel"><h3>How to reason through ${esc(subj(id).name.toLowerCase())}</h3><p>${esc(guide.overview)}</p><div class="study-guide-grid"><div><h4>Key language</h4><dl>${guide.terms.map(([term,definition])=>`<dt>${esc(term)}</dt><dd>${esc(definition)}</dd>`).join('')}</dl></div><div><h4>Make the distinction</h4><table><tbody>${guide.comparison.map(([term,definition])=>`<tr><th scope="row">${esc(term)}</th><td>${esc(definition)}</td></tr>`).join('')}</tbody></table><p class="notice"><strong>Retrieval task</strong><br>${esc(guide.task)}</p></div></div></section>`:''}${bs.length?`<div class="textbook-grid">${bs.map(bookCard).join('')}</div>`:'<p class="muted">Dedicated specialist textbook coverage has not been imported for this subject. Its learning path and external references remain available below.</p>'}</section>`;}
function lessonDepth(l){const expansion=LESSON_EXPANSIONS[l.id];const targets=LESSON_TEXTBOOK_LINKS[l.id]||[];return `<section class="lesson-depth"><span class="eyebrow">GO BEYOND THE OVERVIEW</span>${expansion?`<h3>Why the mechanism matters</h3><p>${esc(expansion.why)}</p><div class="notice"><strong>Common reasoning trap</strong><p>${esc(expansion.pitfall)}</p></div><details><summary>Apply it: ${esc(expansion.prompt)}</summary><p>${esc(expansion.answer)}</p></details>`:''}${targets.length?`<h3>Read the full source chapter</h3><div class="lesson-source-chapters">${targets.map(t=>{const b=textbook(t.book);return `<a href="#book/${b.id}/${t.page}"><strong>${esc(t.title)}</strong><span>${esc(b.shortTitle)} · PDF p. ${t.page} · ${esc(b.level)}</span></a>`}).join('')}</div>`:'<a class="btn secondary" href="#study">Browse the full textbook library</a>'}</section>`;}
function fullTextbookSources(){return `<section class="subject-references"><h2>Full textbook imports</h2><p>${TEXTBOOKS.length} complete, openly licensed books are stored locally with all original pages, figures, tables, references and source learning activities. A separate text extraction powers page search; extracted text is subject to each source book’s license. Imported books are retained unchanged and do not imply author endorsement of Medico.</p>${TEXTBOOKS.map(textbookCredit).join('')}<p class="fine">Imported 9 October 2026. File hashes, licenses, source URLs, page totals and exact section destinations are recorded in textbooks/manifest.json. These editions cover selected topics; they are not an exhaustive NMC competency or NEET PG question-bank corpus.</p></section>`;}

document.addEventListener('submit',e=>{if(e.target.id==='study-search-form'){e.preventDefault();searchTextbooks($('#study-search').value);}if(e.target.id==='reader-page-form'){e.preventDefault();const b=textbook(e.target.dataset.book);if(b)navigate(`#book/${b.id}/${safeBookPage(b,$('#reader-page-number').value)}`);}});
document.addEventListener('input',e=>{if(e.target.id==='reader-chapter-search'){const parts=location.hash.slice(1).split('/');const b=textbook(parts[1]);if(b)$('#reader-chapters').innerHTML=bookChapterLinks(b,safeBookPage(b,parts[2]),e.target.value);}});
document.addEventListener('change',e=>{if(e.target.id==='study-subject'){studySubject=e.target.value;renderStudyBooks();if(studyQuery)searchTextbooks(studyQuery);}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='study-clear'){studySearchToken++;studySearching=false;studyQuery='';studyResults=[];studySearchError='';studySearchPage=0;$('#study-search').value='';renderStudyResults();}if(a==='study-prev'){studySearchPage=Math.max(0,studySearchPage-1);renderStudyResults();}if(a==='study-next'){studySearchPage++;renderStudyResults();}if(a==='reader-next'||a==='reader-prev'){const book=textbook(b.dataset.id);if(book)navigate(`#book/${book.id}/${safeBookPage(book,Number(b.dataset.page)+(a==='reader-next'?1:-1))}`);}if(a==='reader-mode'){readerTextMode=b.dataset.id==='text';const parts=location.hash.slice(1).split('/');bookPage(parts[1],parts[2]);}});
